    const salas = crearSalas()
    const tema = 'estacion-p:Tema12345678'
    const conexion1 = {}
    const conexion2 = {}
    salas.entrar(tema, conexion1)
    salas.entrar(tema, conexion2)
    expect(salas.presencia(tema)).toBe(2)
    salas.salir(conexion1)
    expect(salas.presencia(tema)).toBe(1)
